const norm = $('Eingabe normalisieren').first().json;
const profil = $('Profil laden').first().json || {};
const klein = x => String(x || '').trim().toLowerCase();
const qus = $('Grocy-Einheiten laden').all().map(i => i.json).filter(q => q && q.id);
const quCode = {};
for (const q of qus) quCode[q.id] = klein(q.name) === 'gramm' ? 'g' : klein(q.name) === 'milliliter' ? 'ml' : klein(q.name) === 'stück' ? 'stk' : q.name;
const nw = {};
for (const i of $('Nährwerte laden').all()) if (i.json && i.json.grocy_product_id) nw[i.json.grocy_product_id] = i.json;
const bestand = $('Grocy-Bestand laden').all().map(i => i.json).filter(r => r && r.product_id && Number(r.amount) > 0);
const zone = 'Europe/Berlin';
const heute = DateTime.now().setZone(zone).startOf('day');

const vorrat = bestand.map(r => {
  const p = r.product || {};
  const m = r.best_before_date && !String(r.best_before_date).startsWith('2999') ? DateTime.fromISO(String(r.best_before_date).slice(0, 10), { zone }) : null;
  const n = nw[r.product_id] || {};
  const e = { product_id: Number(r.product_id), name: p.name, menge: Math.round(Number(r.amount) * 10) / 10, einheit: quCode[p.qu_id_stock] || 'stk', tage_bis_mhd: m ? Math.round(m.diff(heute, 'days').days) : null };
  if (n.kcal_100 != null) e.pro_100g = { kcal: n.kcal_100, p: n.protein_100, f: n.fett_100, kh: n.kh_100 };
  if (n.gramm_pro_stk) e.gramm_pro_stk = n.gramm_pro_stk;
  if (n.nutriscore) e.nutriscore = n.nutriscore;
  if (n.nova) e.nova = n.nova;
  return e;
}).sort((a, b) => (a.tage_bis_mhd ?? 999) - (b.tage_bis_mhd ?? 999));

const hatZiele = Number(profil.kcal) > 0;
const ziele_text = hatZiele
  ? 'Tagesziel: ' + profil.kcal + ' kcal, ' + profil.protein_g + ' g Protein, ' + profil.fett_g + ' g Fett, ' + profil.kh_g + ' g Kohlenhydrate.'
  : 'Keine Ziele hinterlegt: ausgewogen mit ca. 2000 kcal pro Tag und ca. 25-30 % Protein planen.';
const mahlzeiten = Number(profil.mahlzeiten_pro_tag) || 3;
const slots = ['Frühstück', 'Mittag', 'Abend', 'Snack', 'Snack 2'].slice(0, Math.max(1, Math.min(5, mahlzeiten)));
const start = heute.plus({ days: 1 });

let aufgabe;
if (norm.modus === 'wochenplan') {
  aufgabe = 'AUFGABE: Erstelle einen gesunden Wochenplan für 7 Tage von ' + start.toISODate() + ' bis ' + start.plus({ days: 6 }).toISODate()
    + ' mit genau diesen Mahlzeiten pro Tag: ' + slots.join(', ') + '. '
    + 'Die Summe aller Mahlzeiten eines Tages soll die Tagesziele möglichst genau treffen (Abweichung max. 10 %). '
    + 'Verplane zuerst Zutaten, die bald ablaufen (kleine tage_bis_mhd zuerst). '
    + 'Nutze Meal-Prep: Reste vom Abendessen dürfen am nächsten Tag mittags wiederkommen. Frühstück darf sich wiederholen. '
    + 'Setze bei jedem Rezept das Feld "tag" auf das Datum.';
} else {
  aufgabe = 'AUFGABE: Schlage genau 3 einfache, gesunde Rezepte (je 1 Portion) vor, die überwiegend den vorhandenen Vorrat nutzen. '
    + 'Priorisiere Zutaten mit tage_bis_mhd <= 3. Jede Portion soll etwa ein Tagesziel geteilt durch ' + mahlzeiten + ' treffen. '
    + 'Setze "tag" auf ' + heute.toISODate() + ' und "mahlzeit" passend (Frühstück/Mittag/Abend/Snack).';
}
if (norm.hinweis) aufgabe += ' Zusatzwunsch des Nutzers: ' + norm.hinweis;

const format = 'ANTWORTFORMAT (nur dieses JSON, nichts anderes):\n'
  + '{"hinweis":"1 kurzer Satz, welche Zutaten zuerst verbraucht werden sollten",'
  + '"rezepte":[{"titel":"...","tag":"YYYY-MM-DD","mahlzeit":"Frühstück","portionen":1,"dauer_min":20,'
  + '"kcal":550,"protein_g":40,"fett_g":18,"kh_g":55,'
  + '"zutaten":[{"product_id":12,"name":"Zucchini","menge":200,"einheit":"g"}],'
  + '"anleitung":["Schritt 1","Schritt 2"]}]}\n'
  + 'REGELN: product_id nur aus dem VORRAT verwenden und dann exakt dessen Einheit nutzen. '
  + 'Zutaten, die nicht im Vorrat sind, mit "product_id": null angeben (landen auf der Einkaufsliste). '
  + 'Berechne kcal und Makros aus den Mengen und den Werten pro_100g (bei stk über gramm_pro_stk); nur wo diese fehlen, realistisch schätzen. '
  + 'Bevorzuge Produkte mit Nutri-Score A/B und NOVA 1-3; Produkte mit Nutri-Score D/E oder NOVA 4 nur sparsam einsetzen.';

const system = 'Du bist Ernährungscoach und Koch. Alles muss gesund sein: viel Gemüse, Hülsenfrüchte, Vollkorn, mageres Protein, gesunde Fette, '
  + 'wenig Zucker und wenig stark verarbeitete Lebensmittel. Rezepte sind einfach: max. 8 Zutaten, max. 30 Minuten, Alltagsküche. '
  + 'Grundzutaten (Salz, Pfeffer, Gewürze, Öl, Essig, Senf, Brühe) gelten als vorhanden und werden nicht als Zutat aufgeführt. '
  + 'Vorlieben des Nutzers: ' + (profil.vorlieben || 'keine') + '. Antworte ausschließlich mit gültigem JSON.';

const prompt = aufgabe + '\n\n' + ziele_text + '\n\nVORRAT (sortiert nach Ablaufdatum):\n' + JSON.stringify(vorrat) + '\n\n' + format;

return [{ json: { modus: norm.modus, chat_id: String(profil.chat_id || ''), ziele_text, vorrat, system, prompt } }];

const ctx = $('Kontext bauen').first().json;
const res = $input.first().json;
let s = String((res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || '');
if (s.includes('</think>')) s = s.split('</think>').pop();
const a = s.indexOf('{');
const b = s.lastIndexOf('}');
if (a < 0 || b < 0) throw new Error('KI-Antwort enthält kein JSON: ' + s.slice(0, 300));
const data = JSON.parse(s.slice(a, b + 1));

const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r1 = x => Math.round((Number(x) || 0) * 10) / 10;
const inv = {};
for (const v of ctx.vorrat) inv[v.product_id] = v;
const bedarf = {};
const einkauf = {};
const addEinkauf = (name, menge, einheit, product_id) => {
  const k = String(name || '').toLowerCase().trim() + '|' + (einheit || '');
  if (!einkauf[k]) einkauf[k] = { name, menge: 0, einheit: einheit || '', product_id: product_id || null };
  einkauf[k].menge += Number(menge) || 0;
};
const heute = DateTime.now().setZone('Europe/Berlin').toISODate();
const rezepte = Array.isArray(data.rezepte) ? data.rezepte : [];
if (!rezepte.length) throw new Error('KI hat keine Rezepte geliefert');

const out = rezepte.map(r => {
  const zutaten = (r.zutaten || []).map(z => {
    const v = z.product_id != null ? inv[z.product_id] : null;
    return { product_id: v ? v.product_id : null, name: z.name || (v && v.name) || '?', menge: Number(z.menge) || 0, einheit: v ? v.einheit : (z.einheit || '') };
  });
  for (const z of zutaten) {
    if (z.product_id != null) bedarf[z.product_id] = (bedarf[z.product_id] || 0) + z.menge;
    else addEinkauf(z.name, z.menge, z.einheit);
  }
  const schritte = Array.isArray(r.anleitung) ? r.anleitung : String(r.anleitung || '').split('\n').filter(Boolean);
  const anleitung = schritte.map((t, i) => (i + 1) + '. ' + String(t).replace(/^\s*\d+[.)]\s*/, '')).join('\n');
  const zText = zutaten.map(z => '• ' + (z.menge ? r1(z.menge) + ' ' + esc(z.einheit) + ' ' : '') + esc(z.name) + (z.product_id == null ? ' 🛒' : '')).join('\n');
  const kcal = Math.round(r.kcal || 0), p = Math.round(r.protein_g || 0), f = Math.round(r.fett_g || 0), kh = Math.round(r.kh_g || 0);
  const nachricht = '<b>🍳 ' + esc(r.titel) + '</b>\n'
    + (r.mahlzeit ? esc(r.mahlzeit) + ' · ' : '') + kcal + ' kcal · P ' + p + ' g · F ' + f + ' g · KH ' + kh + ' g'
    + (r.dauer_min ? ' · ⏱ ' + r.dauer_min + ' Min' : '')
    + '\n\n<b>Zutaten</b> (🛒 = fehlt noch)\n' + zText
    + '\n\n<b>Zubereitung</b>\n' + esc(anleitung);
  return { titel: String(r.titel || 'Rezept'), typ: ctx.modus, geplant_fuer: r.tag || heute, mahlzeit: String(r.mahlzeit || ''), portionen: Number(r.portionen) || 1,
    kcal, protein_g: p, fett_g: f, kh_g: kh, zutaten_json: JSON.stringify(zutaten), anleitung, status: 'vorgeschlagen', nachricht };
});

for (const id of Object.keys(bedarf)) {
  const v = inv[id];
  const fehlt = bedarf[id] - (Number(v.menge) || 0);
  if (fehlt > 0.01) addEinkauf(v.name, fehlt, v.einheit, v.product_id);
}
const liste = Object.values(einkauf).sort((x, y) => String(x.name).localeCompare(String(y.name)))
  .map(e => '☐ ' + (e.menge ? Math.ceil(e.menge) + ' ' + esc(e.einheit) + ' ' : '') + esc(e.name)).join('\n');
const einkaufText = '<b>🛒 Einkaufsliste für die Woche</b>\n' + (liste || 'Alles da, nichts einzukaufen! 🎉');

const reihenfolge = { 'Frühstück': 0, 'Mittag': 1, 'Abend': 2, 'Snack': 3, 'Snack 2': 4 };
const tage = {};
for (const r of out) (tage[r.geplant_fuer] = tage[r.geplant_fuer] || []).push(r);
let uebersicht = (data.hinweis ? '💡 ' + esc(data.hinweis) + '\n\n' : '') + '<b>📅 Dein Wochenplan</b>\n' + esc(ctx.ziele_text) + '\n';
for (const tag of Object.keys(tage).sort()) {
  const l = tage[tag].sort((x, y) => (reihenfolge[x.mahlzeit] ?? 9) - (reihenfolge[y.mahlzeit] ?? 9));
  const sum = k => l.reduce((acc, r) => acc + (Number(r[k]) || 0), 0);
  uebersicht += '\n<b>' + DateTime.fromISO(tag).setLocale('de').toFormat('ccc dd.LL.') + '</b> · ' + sum('kcal') + ' kcal · P ' + sum('protein_g') + ' / F ' + sum('fett_g') + ' / KH ' + sum('kh_g') + ' g\n'
    + l.map(r => '  ' + esc(r.mahlzeit) + ': ' + esc(r.titel) + ' (' + r.kcal + ' kcal)').join('\n') + '\n';
}
uebersicht += '\nDie Rezepte bekommst du jeden Morgen einzeln mit „✅ Gekocht“-Button.';

if (ctx.modus !== 'wochenplan' && data.hinweis) out[0].nachricht = '💡 ' + esc(data.hinweis) + '\n\n' + out[0].nachricht;
const einkaufListe = Object.values(einkauf).map(e => ({ ...e, menge: Math.ceil(e.menge) }));
return out.map(o => ({ json: { ...o, uebersicht, einkaufText, einkauf: einkaufListe, chat_id: ctx.chat_id } }));

const liste = $('Antwort auswerten').first().json.einkauf || [];
const kw = DateTime.now().setZone('Europe/Berlin').plus({ days: 1 }).toFormat('W');
return liste.map(e => ({ json: { body: e.product_id
  ? { shopping_list_id: 1, product_id: e.product_id, amount: e.menge, note: 'Wochenplan KW ' + kw }
  : { shopping_list_id: 1, amount: 1, note: e.name + (e.menge ? ' (' + e.menge + ' ' + e.einheit + ')' : '') + ' – Wochenplan KW ' + kw } } }));
